class StdinTests(CliCase):
    def test_all_commands_read_stdin(self):
        for argv, want in [
            (("balance", "-"), "1457.50\n"),
            (("summary", "-", "--by", "month"), "2024-03  1457.50\n"),
            (("list", "-", "--category", "groceries"), "2024-03-02 groceries -42.50 weekly shop\n"),
            (("export", "-"), None),
        ]:
            code, out, err = self.run_cli(*argv, stdin=LEDGER)
            self.assertEqual((code, err), (0, ""), argv)
            if want is not None:
                self.assertEqual(out, want)
            else:
                self.assertTrue(out.startswith("date,category,amount,note\n2024-03-01,salary,2500.00,March pay\n"))

    def test_stdin_error(self):
        code, out, err = self.run_cli("balance", "-", stdin="2024-03-01 a 1\nbad\n")
        self.assertEqual((code, out), (1, ""))
        self.assertIn("line 2", err)

    def test_stdin_bytes(self):
        fake = mock.Mock()
        fake.buffer.read.return_value = "2024-03-01 a 1\n".encode("utf-8")
        with mock.patch.object(sys, "stdin", fake):
            self.assertEqual(self.run_cli("balance", "-")[:2], (0, "1.00\n"))


class LedgerErrorTests(CliCase):
    def test_exit_1_names_line_with_empty_stdout(self):
        bad = self.write("bad.txt", "# c\n\n2024-03-01 a 1\n2024-02-30 b 2\n")
        for argv in (("balance",), ("summary",), ("summary", "--json"), ("list",), ("list", "--json"), ("export",)):
            code, out, err = self.run_cli(*argv[:1], bad, *argv[1:])
            self.assertEqual((code, out), (1, ""), argv)
            self.assertIn("line 4", err)
            self.assertTrue(err.startswith("pennywise: "))

    def test_error_found_even_if_filtered_out(self):
        bad = self.write("bad.txt", "2024-03-01 a 1\nbroken\n")
        code, out, err = self.run_cli("list", bad, "--category", "a")
        self.assertEqual((code, out), (1, ""))
        self.assertIn("line 2", err)


class UsageErrorTests(CliCase):
    def assert_usage_error(self, *argv):
        code, out, err = self.run_cli(*argv)
        self.assertEqual((code, out), (2, ""), argv)
        self.assertIn("pennywise: ", err)

    def test_missing_file(self):
        self.assert_usage_error("balance", os.path.join(self.dir, "missing.txt"))
        self.assert_usage_error("list", self.dir)

    def test_non_utf8_file(self):
        p = self.write("latin.txt", b"2024-03-01 caf\xe9 1\n", binary=True)
        self.assert_usage_error("balance", p)

    def test_no_command(self):
        self.assert_usage_error()

    def test_unknown_command(self):
        self.assert_usage_error("frobnicate", self.path)

    def test_missing_file_argument(self):
        self.assert_usage_error("balance")

    def test_bad_option_values(self):
        self.assert_usage_error("summary", self.path, "--by", "year")
        self.assert_usage_error("list", self.path, "--bogus")

    def test_malformed_dates(self):
        for opt in ("--since", "--until"):
            for value in ("2024-3-1", "yesterday", "2024-02-30", "2024-03-01x", ""):
                self.assert_usage_error("list", self.path, opt, value)

    def test_help_is_success(self):
        code, out, _ = self.run_cli("--help")
        self.assertEqual(code, 0)
        self.assertIn("balance", out)


class AddTests(CliCase):
    def test_add_creates_file_and_prints_line(self):
        p = os.path.join(self.dir, "new.txt")
        self.assertEqual(
            self.run_cli("add", p, "2024-03-09", "Coffee", "-3.5", "morning  brew"),
            (0, "2024-03-09 coffee -3.50 morning  brew\n", ""),
        )
        self.assertEqual(self.read_bytes(p), b"2024-03-09 coffee -3.50 morning  brew\n")

    def test_add_without_note(self):
        p = os.path.join(self.dir, "new.txt")
        self.assertEqual(self.run_cli("add", p, "2024-03-09", "Rent", "+900"), (0, "2024-03-09 rent 900.00\n", ""))

    def test_add_appends_after_existing(self):
        before = self.read_bytes(self.path)
        self.run_cli("add", self.path, "2024-03-09", "x", "1")
        self.assertEqual(self.read_bytes(self.path), before + b"2024-03-09 x 1.00\n")

    def test_add_inserts_newline_when_missing(self):
        p = self.write("nonl.txt", "2024-03-01 a 1")
        self.run_cli("add", p, "2024-03-09", "x", "1")
        self.assertEqual(self.read_bytes(p), b"2024-03-01 a 1\n2024-03-09 x 1.00\n")

    def test_add_to_empty_existing_file(self):
        p = self.write("empty.txt", "")
        self.run_cli("add", p, "2024-03-09", "x", "1")
        self.assertEqual(self.read_bytes(p), b"2024-03-09 x 1.00\n")

    def test_add_keeps_crlf_file_intact(self):
        p = self.write("crlf.txt", b"2024-03-01 a 1\r\n", binary=True)
        self.run_cli("add", p, "2024-03-09", "x", "1")
        self.assertEqual(self.read_bytes(p), b"2024-03-01 a 1\r\n2024-03-09 x 1.00\n")

    def test_add_does_not_validate_existing_content(self):
        p = self.write("junk.txt", "junk\n")
        self.assertEqual(self.run_cli("add", p, "2024-03-09", "x", "1")[0], 0)
        self.assertEqual(self.read_bytes(p), b"junk\n2024-03-09 x 1.00\n")

    def test_add_round_trips_through_list(self):
        p = os.path.join(self.dir, "rt.txt")
        self.run_cli("add", p, "2024-03-09", "Coffee", "-3.5", "a  b")
        self.assertEqual(self.run_cli("list", p)[1], "2024-03-09 coffee -3.50 a  b\n")

    def test_invalid_entries_refused_file_untouched(self):
        before = self.read_bytes(self.path)
        bad = [
            ("2024-02-30", "x", "1", ""),
            ("2024-3-1", "x", "1", ""),
            ("2024-03-01", "x", "12.505", ""),
            ("2024-03-01", "x", "1,000.00", ""),
            ("2024-03-01", "x", "abc", ""),
            ("2024-03-01", "two words", "1", ""),
            ("2024-03-01", "", "1", ""),
            ("2024-03-01", "x", "", ""),
            ("", "x", "1", ""),
            ("2024-03-01", "x", "1", "line one\nline two"),
            ("2024-03-01", "x", "1", "carriage\rreturn"),
            ("2024-03-01 ", "x", "1", ""),
            ("2024-03-01", "x", "1 2", ""),
        ]
        for date, cat, amount, note in bad:
            argv = ["add", self.path, date, cat, amount] + ([note] if note else [])
            code, out, err = self.run_cli(*argv)
            self.assertEqual((code, out), (1, ""), argv)
            self.assertIn("line 1", err, argv)
            self.assertEqual(self.read_bytes(self.path), before, argv)

    def test_invalid_entry_does_not_create_file(self):
        p = os.path.join(self.dir, "never.txt")
        code, out, err = self.run_cli("add", p, "2024-02-30", "x", "1")
        self.assertEqual((code, out), (1, ""))
        self.assertIn("line 1", err)
        self.assertFalse(os.path.exists(p))

    def test_unwritable_target_is_exit_2(self):
        code, out, err = self.run_cli("add", self.dir, "2024-03-09", "x", "1")
        self.assertEqual((code, out), (2, ""))
        self.assertIn("pennywise:", err)

    def test_add_missing_args_is_exit_2(self):
        self.assertEqual(self.run_cli("add", self.path, "2024-03-09")[0], 2)


class SubprocessTests(CliCase):
    def run_module(self, *argv, stdin=None):
        env = dict(os.environ, PYTHONPATH=ROOT)
        return subprocess.run(
            [sys.executable, "-m", "pennywise", *argv],
            input=stdin, capture_output=True, text=True, env=env, cwd=self.dir,
        )

    def test_module_balance(self):
        r = self.run_module("balance", self.path)
        self.assertEqual((r.returncode, r.stdout, r.stderr), (0, "1457.50\n", ""))

    def test_module_stdin(self):
        r = self.run_module("balance", "-", stdin=LEDGER)
        self.assertEqual((r.returncode, r.stdout), (0, "1457.50\n"))

    def test_module_ledger_error(self):
        bad = self.write("bad.txt", "oops\n")
        r = self.run_module("balance", bad)
        self.assertEqual((r.returncode, r.stdout), (1, ""))
        self.assertIn("line 1", r.stderr)

    def test_module_usage_error(self):
        r = self.run_module()
        self.assertEqual((r.returncode, r.stdout), (2, ""))


